CREATE TABLE legal_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy text NOT NULL CHECK(policy IN('privacy','terms')),version integer NOT NULL,html text NOT NULL,content_hash text NOT NULL,effective_date date NOT NULL,material boolean NOT NULL DEFAULT true,published_at timestamptz NOT NULL DEFAULT now(),actor_id uuid NOT NULL REFERENCES users(id),UNIQUE(policy,version));
CREATE TABLE legal_drafts(policy text PRIMARY KEY CHECK(policy IN('privacy','terms')),html text NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 1,effective_date date NOT NULL DEFAULT CURRENT_DATE,updated_at timestamptz NOT NULL DEFAULT now(),actor_id uuid REFERENCES users(id));
CREATE TABLE legal_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),policy_version_id uuid NOT NULL REFERENCES legal_versions(id),workflow text NOT NULL,reference_id uuid,accepted_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_legal_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Legal history is immutable'; END $$;
CREATE TRIGGER immutable_legal_versions BEFORE UPDATE OR DELETE ON legal_versions FOR EACH ROW EXECUTE FUNCTION immutable_legal_record();
CREATE TRIGGER immutable_legal_consents BEFORE UPDATE OR DELETE ON legal_consents FOR EACH ROW EXECUTE FUNCTION immutable_legal_record();
